import * as THREE from 'three';
import { createRenderer } from './core/renderer.js';
import { createScene } from './core/scene.js';
import { createCamera } from './core/camera.js';
import { setupXR } from './core/xr.js';
import { initHandTracking } from './systems/handTracking.js';
import { createInteractionSystem } from './systems/interaction.js';
import { createPhysicsSystem } from './systems/physics.js';
import { apiClient } from './api/client.js';
import { createHUD } from './ui/hud.js';
import { createModuleRuntime } from './modules/moduleRuntime.js';

const scene = createScene();
const camera = createCamera();
const renderer = createRenderer();

setupXR(renderer);
document.body.style.margin = '0';
document.body.appendChild(renderer.domElement);

const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(10, 10),
    new THREE.MeshStandardMaterial({ color: '#94a3b8' })
);
floor.rotation.x = -Math.PI / 2;
scene.add(floor);

const handTracking = initHandTracking(renderer);
const interaction = createInteractionSystem();
const physics = createPhysicsSystem();
const hud = createHUD();

let moduleRuntime = null;

async function bootstrapLearningRuntime() {
    hud.setCard({
        titleText: 'Loading Session',
        subtitleText: 'Fetching module outline from backend...',
        tipsText: 'Ensure server is running on port 3000.',
    });

    try {
        const session = await apiClient.getLearningSession();
        moduleRuntime = createModuleRuntime({
            scene,
            interaction,
            hud,
            session,
        });
        moduleRuntime.start();
    } catch (error) {
        hud.setCard({
            titleText: 'Failed to Load Session',
            subtitleText: String(error.message || error),
            tipsText: 'Start backend with npm run dev:server then refresh.',
        });
    }
}

bootstrapLearningRuntime();

window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

renderer.setAnimationLoop(() => {
    const hands = handTracking.getHands();
    const _handCount = hands.length;
    physics.step(1 / 72);
    interaction.update({ hands, scene, camera });
    moduleRuntime?.update(1 / 72);
    renderer.render(scene, camera);
});
